//! One tree in winter: an old pedunculate oak, stag-headed, standing alone
//! on a low rise of snow under a pale overcast sky. Seen from low down (the
//! horizon crosses the lower trunk, as Friedrich marked it on his studies
//! drawn sitting on the ground). Two of its upper limbs are dead and bare
//! of bark, one ends in a clean sawn-looking stump; the living lower crown
//! is a dense net of crooked short shoots. Wet snow lies along the tops of
//! the level limbs and in the forks.
//!
//!   cargo paint r13_tree2 -- --full --width 2400
//!   cargo paint r13_tree2 -- --full --width 2400 --crop 380,560,620,760
//!
//! Order of work (as the sources give it): underdrawing of the trunk and
//! scaffold limbs in pencil, sky (lay-in, fused, stippled), the snowfield,
//! then the tree over the finished sky, thick to thin, the snow on the
//! limbs, and the small things last (weeds through the snow, dead leaves).

use paint::graphite::{Lead, Mark};
use paint::{Fbm, Gesture, Held, Mask, Mix, Paint, Rgb, Rng, Shape, Stipple, Style, Tool, Touch, gradient, hex, smoothstep};
use std::f32::consts::{FRAC_PI_2, PI};

const ASPECT: f32 = 0.8; // 1000 x 1250 units
const HORIZON: f32 = 1004.0;
const FOOT: (f32, f32) = (488.0, 1136.0);

/// One branch as drawn: a polyline with a full width at each point.
#[derive(Clone)]
struct Br {
    pts: Vec<(f32, f32)>,
    w: Vec<f32>,
    dead: bool,
    /// ends in a live growing tip (lifted off to a point)
    tip: bool,
}

fn ang_diff(to: f32, from: f32) -> f32 {
    let mut d = to - from;
    while d > PI {
        d -= 2.0 * PI;
    }
    while d < -PI {
        d += 2.0 * PI;
    }
    d
}

/// Grow a branch from `p` at angle `a` (canvas angle, y down) and width `w`
/// (units): a crooked oak shoot. Side branches leave at internodes whose
/// length grows with the width; each fork takes its share of the parent's
/// cross-section (Leonardo, exponent `DELTA`); the parent kinks away from
/// the child (sympodial takeover). Thin shoots turn upward, heavy ones sag.
fn grow(rng: &mut Rng, out: &mut Vec<Br>, p: (f32, f32), a0: f32, w0: f32, dead: bool, vigor: f32) {
    const DELTA: f32 = 1.9;
    let wmin = 0.34;
    if out.len() > 60_000 {
        return;
    }
    let mut pts = vec![p];
    let mut ws = vec![w0];
    let mut a = a0;
    let mut w = w0;
    let mut pos = p;
    let mut to_fork = internode(w, rng);
    let mut kids: Vec<((f32, f32), f32, f32)> = vec![];
    let mut tip = !dead;
    let mut guard = 0;
    loop {
        guard += 1;
        if guard > 400 {
            break;
        }
        let step = (1.6 + 0.9 * w).min(10.0);
        // crooked: thin shoots wander more, thick limbs hold their line
        a += rng.normal() * (0.05 + 0.22 / (1.0 + 0.6 * w));
        // tropism: thin shoots turn up toward the light, heavy near-level
        // limbs sag a little under their own weight
        let up = -FRAC_PI_2;
        if w < 4.0 {
            a += ang_diff(up, a) * 0.035 * vigor;
        } else if a.cos().abs() > 0.5 {
            let down = if a.cos() > 0.0 { 0.0 } else { PI };
            a += ang_diff(down, a) * 0.01;
        }
        pos = (pos.0 + step * a.cos(), pos.1 + step * a.sin());
        // gradual taper between forks
        w *= (-step * 0.0035).exp();
        pts.push(pos);
        ws.push(w);
        if pos.1 > HORIZON + 60.0 || pos.0 < -40.0 || pos.0 > 1040.0 || pos.1 < -40.0 {
            tip = false;
            break;
        }
        to_fork -= step;
        if to_fork <= 0.0 {
            to_fork = internode(w, rng);
            // an old oak sheds much of its fine growth: short shoots stay
            // short, some forks abort
            if w < 1.6 && rng.chance(0.18 + (1.0 - vigor) * 0.25) {
                continue;
            }
            let r = rng.range(0.45, 0.82);
            let wc = w * r;
            let wp = (w.powf(DELTA) - wc.powf(DELTA)).max(0.0).powf(1.0 / DELTA).max(wc * 0.9);
            let side = if rng.chance(0.5) { 1.0 } else { -1.0 };
            let spread = rng.range(0.45, 1.05) * (0.7 + 0.3 * r);
            // the child takes the lead as often as not: the old axis kinks
            let kink = rng.range(0.08, 0.35) * (1.0 - 0.4 * r);
            kids.push((pos, a + side * spread, wc));
            a -= side * kink;
            w = wp;
        }
        if w < wmin {
            break;
        }
        if dead && w < 3.0 && rng.chance(0.25) {
            // dead limbs lose their fine wood: a broken stub
            break;
        }
    }
    out.push(Br { pts, w: ws, dead, tip });
    for (q, ka, kw) in kids {
        if kw < wmin {
            continue;
        }
        grow(rng, out, q, ka, kw, dead, vigor);
    }
}

fn internode(w: f32, rng: &mut Rng) -> f32 {
    (4.0 + 2.6 * w).min(70.0) * rng.range(0.6, 1.4)
}

/// Resample a hand-placed polyline smoothly every `step` units with widths
/// interpolated along its length.
fn smooth(ctrl: &[(f32, f32, f32)], step: f32) -> (Vec<(f32, f32)>, Vec<f32>) {
    let pts: Vec<(f32, f32)> = ctrl.iter().map(|c| (c.0, c.1)).collect();
    let dense = paint::graphite::resample(&pts, true, step);
    // widths by arc-length fraction of the control polygon
    let mut cl = vec![0.0f32];
    for i in 1..ctrl.len() {
        cl.push(cl[i - 1] + ((ctrl[i].0 - ctrl[i - 1].0).powi(2) + (ctrl[i].1 - ctrl[i - 1].1).powi(2)).sqrt());
    }
    let mut dl = vec![0.0f32];
    for i in 1..dense.len() {
        dl.push(dl[i - 1] + ((dense[i].0 - dense[i - 1].0).powi(2) + (dense[i].1 - dense[i - 1].1).powi(2)).sqrt());
    }
    let (ct, dt) = (*cl.last().unwrap(), dl.last().unwrap().max(1e-3));
    let ws = dl
        .iter()
        .map(|&d| {
            let s = d / dt * ct;
            let k = cl.partition_point(|&c| c <= s).clamp(1, ctrl.len() - 1);
            let t = ((s - cl[k - 1]) / (cl[k] - cl[k - 1]).max(1e-3)).clamp(0.0, 1.0);
            ctrl[k - 1].2 + (ctrl[k].2 - ctrl[k - 1].2) * t
        })
        .collect();
    (dense, ws)
}

/// The oak: the trunk and scaffold limbs placed by hand (the "study from
/// nature"), everything finer grown from them.
struct Tree {
    trunk: Br,
    limbs: Vec<Br>,
    all: Vec<Br>,
}

fn build_tree(seed: u64) -> Tree {
    let mut rng = Rng::new(seed);
    let (fx, fy) = FOOT;
    // trunk: a root flare, a slight lean and twist, dividing about 700
    let (tp, tw) = smooth(
        &[(fx, fy + 6.0, 150.0), (fx + 2.0, fy - 22.0, 104.0), (fx + 4.0, fy - 70.0, 86.0), (fx - 3.0, fy - 170.0, 80.0), (fx + 4.0, fy - 290.0, 76.0), (fx + 12.0, fy - 380.0, 74.0), (fx + 16.0, fy - 430.0, 80.0)],
        3.0,
    );
    let trunk = Br { pts: tp, w: tw, dead: false, tip: false };
    let top = (fx + 16.0, fy - 430.0); // ~ (504, 706)
    // scaffold limbs (x, y, width); dead ones silver and bare
    let defs: Vec<(Vec<(f32, f32, f32)>, bool, f32)> = vec![
        // A: the great left bough, up and out, then level and twisting
        (vec![(top.0 - 14.0, top.1 + 6.0, 42.0), (440.0, 640.0, 34.0), (360.0, 585.0, 27.0), (290.0, 560.0, 22.0), (225.0, 520.0, 17.0), (170.0, 505.0, 12.0), (120.0, 470.0, 8.0)], false, 1.0),
        // B: centre-left leader, alive low, dead above (stag-head)
        (vec![(top.0 - 6.0, top.1, 44.0), (480.0, 600.0, 36.0), (462.0, 500.0, 30.0), (440.0, 420.0, 25.0), (432.0, 360.0, 21.0)], false, 0.9),
        (vec![(432.0, 362.0, 21.0), (420.0, 290.0, 16.0), (402.0, 225.0, 13.0), (410.0, 170.0, 10.0), (398.0, 132.0, 7.0)], true, 0.0),
        // C: the heavy right elbow, nearly level: holds the most snow
        (vec![(top.0 + 18.0, top.1 + 8.0, 40.0), (590.0, 668.0, 33.0), (670.0, 640.0, 27.0), (745.0, 600.0, 22.0), (810.0, 580.0, 16.0), (868.0, 548.0, 11.0), (910.0, 512.0, 7.0)], false, 1.0),
        // D: centre-right riser, dead and broken off short
        (vec![(top.0 + 8.0, top.1 - 4.0, 38.0), (548.0, 600.0, 31.0), (580.0, 500.0, 26.0), (598.0, 420.0, 22.0)], false, 0.9),
        (vec![(598.0, 422.0, 22.0), (612.0, 350.0, 19.0), (628.0, 300.0, 17.0)], true, 0.0),
        // E: a lower left limb from the trunk, drooping then rising
        (vec![(fx - 20.0, fy - 330.0, 24.0), (420.0, 790.0, 19.0), (350.0, 770.0, 15.0), (280.0, 760.0, 11.0), (220.0, 728.0, 8.0)], false, 1.0),
    ];
    let mut limbs = vec![];
    let mut all = vec![];
    for (ctrl, dead, vigor) in &defs {
        let (p, w) = smooth(ctrl, 3.0);
        let br = Br { pts: p.clone(), w: w.clone(), dead: *dead, tip: false };
        // side branches along the scaffold: alternate sides, acrotonic
        // (more and stronger toward its outer end)
        let n = p.len();
        let mut s = rng.range(8.0, 20.0);
        let mut acc = 0.0;
        let mut side = if rng.chance(0.5) { 1.0 } else { -1.0 };
        for i in 1..n {
            acc += ((p[i].0 - p[i - 1].0).powi(2) + (p[i].1 - p[i - 1].1).powi(2)).sqrt();
            if acc < s {
                continue;
            }
            acc = 0.0;
            let t = i as f32 / n as f32;
            s = (w[i] * rng.range(0.9, 2.0)).max(9.0);
            let a = (p[i].1 - p[i - 1].1).atan2(p[i].0 - p[i - 1].0);
            if *dead {
                // a dead limb keeps only a few short stubs
                if rng.chance(0.35) {
                    grow(&mut rng, &mut all, p[i], a + side * rng.range(0.5, 1.1), w[i] * rng.range(0.2, 0.4), true, 0.0);
                }
            } else {
                let share = rng.range(0.25, 0.55) * (0.6 + 0.6 * t);
                grow(&mut rng, &mut all, p[i], a + side * rng.range(0.55, 1.15), (w[i] * share).max(0.6), false, *vigor);
            }
            side = -side;
        }
        // the limb's outer end goes on as grown wood (live ones)
        if !*dead {
            let a = (p[n - 1].1 - p[n - 2].1).atan2(p[n - 1].0 - p[n - 2].0);
            grow(&mut rng, &mut all, p[n - 1], a, w[n - 1], false, *vigor);
        }
        limbs.push(br);
    }
    // epicormic shoots on the old trunk: short straight sprouts
    for k in 0..9 {
        let y = fy - 240.0 - k as f32 * 22.0 + rng.range(-8.0, 8.0);
        let side = if k % 2 == 0 { -1.0 } else { 1.0 };
        let x = fx + 10.0 + side * 36.0;
        let a = -FRAC_PI_2 + side * rng.range(0.4, 0.9);
        grow(&mut rng, &mut all, (x, y), a, rng.range(0.7, 1.4), false, 1.2);
    }
    Tree { trunk, limbs, all }
}

fn main() {
    let o = paintings::run::Run::new("r13_tree2");
    let st = Style::friedrich();
    let pal = &st.palette;
    let mut rng = Rng::new(o.seed);
    let mut c = o.canvas(|| st.prepare(o.width, ASPECT, o.seed));
    let f = c.frame();
    let (w, h) = (c.width(), c.height());

    let tree = build_tree(o.seed + 11);
    eprintln!("  tree: {} grown branches", tree.all.len());

    // ------------------------------------------------------------ geometry
    // the snowfield: a far flat plain to the horizon, the tree's rise in
    // front, sloping gently down to the right and toward us
    let rise = move |x: f32| {
        let d = (x - FOOT.0) / 330.0;
        let knoll = (-d * d).exp();
        HORIZON + 22.0 + 40.0 * (1.0 - knoll) * 0.4 - 18.0 * knoll + 6.0 * (x / 90.0).sin()
    };
    let rise_c = f.per_column(rise);
    let far = Fbm::new(o.seed as u32 + 5, 4, 60.0);
    // a strip of distant wood on the horizon, broken, darker at the left
    let wood_top = f.per_column(move |x: f32| {
        let n = far.get(x, 0.0);
        let band = smoothstep(-0.1, 0.25, n) * (if x < 380.0 { 1.0 } else if x > 640.0 { 0.8 } else { 0.25 });
        HORIZON - 2.0 - band * (7.0 + 9.0 * far.get(x * 3.0, 9.0).abs())
    });
    let sky_m = Mask::from_fn(f, |_, y| if y < HORIZON + 3.0 { 1.0 } else { 0.0 });
    let snow_m = Mask::from_fn(f, |_, y| if y >= HORIZON - 1.0 { 1.0 } else { 0.0 });

    // sky colors: a luminous gray overcast, slightly violet overhead,
    // lightening to a pale warm band low down; soft darker stratus drifts
    let drift = Fbm::new(o.seed as u32 + 3, 5, 260.0);
    let sky_stops: [(f32, Rgb); 5] = [(0.0, hex("#8a8d96")), (0.35, hex("#a4a4a6")), (0.7, hex("#c2beb4")), (0.9, hex("#d8cfbc")), (1.0, hex("#ddd2bd"))];
    let sky_col = move |x: f32, y: f32| {
        let t = (y / HORIZON).clamp(0.0, 1.0);
        let base = gradient(&sky_stops, t, Mix::Pigment);
        // stratus: long level drifts, darker, only in the upper sky
        let s = drift.get(x * 0.35, y * 1.6);
        let k = smoothstep(0.05, 0.45, s) * (1.0 - smoothstep(0.45, 0.85, t)) * 0.55;
        paint::color::mix(base, hex("#7e7f86"), k, Mix::Pigment)
    };

    // snow colors: reflecting the gray sky, bluish in the hollows and toward
    // us, lightest on the rise's crest
    let snowvar = Fbm::new(o.seed as u32 + 7, 4, 90.0);
    let snow_col = move |x: f32, y: f32| {
        let r = rise_c(x);
        let far_t = smoothstep(HORIZON, r + 60.0, y);
        let n = snowvar.get(x * 0.5, y * 1.8);
        let base = gradient(&[(0.0, hex("#c9c7c0")), (0.4, hex("#e3e0d6")), (1.0, hex("#d9d9d4"))], far_t, Mix::Pigment);
        // hollows: bluish gray
        let hollow = smoothstep(0.1, 0.5, n) * (0.3 + 0.5 * far_t);
        let mut col = paint::color::mix(base, hex("#a9b0b8"), hollow, Mix::Pigment);
        // the soft shadow of the rise's far side, and the tree's shade
        // under it (overcast: faint)
        let dx = (x - FOOT.0) / 160.0;
        let dy = (y - FOOT.1 - 8.0) / 28.0;
        let shade = (-(dx * dx + dy * dy)).exp() * 0.35;
        col = paint::color::mix(col, hex("#9aa0a8"), shade, Mix::Pigment);
        if y < r + 3.0 && y > HORIZON + 1.0 {
            // the plain beyond the rise, grayer
            col = paint::color::mix(col, hex("#bdbcb6"), 0.5, Mix::Pigment);
        }
        col
    };

    // the wood: one mask for everything thick enough to be painted as a
    // body (the trunk, the limbs, the thicker grown branches)
    let mut shape = Shape::new().ribbon(&tree.trunk.pts, &tree.trunk.w);
    for b in tree.limbs.iter().chain(tree.all.iter()) {
        if b.w[0] > 2.2 {
            shape = shape.ribbon(&b.pts, &b.w);
        }
    }
    let wood_m = Mask::from_shape(f, shape);

    // ---------------------------------------------------------- drawing
    if o.stage("drawing", &mut c, &mut rng) {
        // pencil on the ground: the trunk's sides and the scaffolds' axes,
        // a faint first pass, then firmer where it matters
        let hb = Lead::pencil("HB").unwrap();
        let b2 = Lead::pencil("2B").unwrap();
        let mut worn = 0.0;
        let mut line = |c: &mut paint::Canvas, lead: &Lead, pts: Vec<(f32, f32)>, p: f32, seed: u64| {
            let n = pts.len();
            let pr = (0..n).map(|i| p * (0.75 + 0.25 * ((i as f32 * 0.37 + seed as f32).sin()))).collect();
            worn += c.draw(lead, &Mark { pts, pressure: pr }, worn, seed);
        };
        let side = |b: &Br, s: f32| -> Vec<(f32, f32)> {
            let n = b.pts.len();
            (0..n)
                .map(|i| {
                    let (a, e) = (b.pts[i.saturating_sub(1)], b.pts[(i + 1).min(n - 1)]);
                    let (dx, dy) = (e.0 - a.0, e.1 - a.1);
                    let l = (dx * dx + dy * dy).sqrt().max(1e-3);
                    (b.pts[i].0 - dy / l * b.w[i] * 0.5 * s, b.pts[i].1 + dx / l * b.w[i] * 0.5 * s)
                })
                .collect()
        };
        line(&mut c, &hb, side(&tree.trunk, 1.0), 0.35, 1);
        line(&mut c, &hb, side(&tree.trunk, -1.0), 0.35, 2);
        for (k, l) in tree.limbs.iter().enumerate() {
            line(&mut c, &hb, side(l, 1.0), 0.3, 10 + k as u64);
            line(&mut c, &hb, side(l, -1.0), 0.3, 20 + k as u64);
        }
        // the horizon, ruled, and the rise
        line(&mut c, &b2, vec![(0.0, HORIZON), (1000.0, HORIZON)], 0.25, 40);
        line(&mut c, &hb, (0..=40).map(|i| (i as f32 * 25.0, rise_c(i as f32 * 25.0))).collect(), 0.2, 41);
        for b in tree.all.iter().filter(|b| b.w[0] > 5.0) {
            line(&mut c, &hb, b.pts.clone(), 0.18, 60);
        }
    }

    // ---------------------------------------------------------------- sky
    if o.stage("sky", &mut c, &mut rng) {
        // lay-in: broad level strokes, thin, then fused with the badger
        let hd = st.broad().color(sky_col).angle(|_, _| 0.0).angle_jitter(0.1).length(40.0, 120.0).coverage(3.4).medium(0.35).clip(true).threshold(0.3);
        c.work(&sky_m, &hd, 101);
        if let Some(b) = st.blend() {
            c.work(&sky_m, &b.clip(true).angle(|_, _| 0.0).angle_jitter(0.15), 102);
        }
        c.dry();
        // stippled over: the gradation again, in small touches of the tip
        let sp = Stipple::new(Tool::stippler(2.2)).mixed(pal, 0.45).color(sky_col).coverage(|_, _| 1.5).pressure(0.4, 0.75).dips(18, 0.4, 0.5).cluster(0.3, None).clip(true);
        c.stipple(&sky_m, &sp, 103);
        c.dry();
    }

    // --------------------------------------------------------------- snow
    if o.stage("snow", &mut c, &mut rng) {
        // the distant wood: a thin dark band, stippled, blue-gray with air
        let wood_band = Mask::from_fn(f, |x, y| if y > wood_top(x) && y < HORIZON + 1.5 { 1.0 } else { 0.0 });
        // snowfield: level strokes, lead white body
        let hd = st.body().color(snow_col).angle(|_, y| if y < HORIZON + 30.0 { 0.0 } else { 0.03 }).angle_jitter(0.12).length(18.0, 60.0).coverage(3.0).medium(0.15).clip(true).threshold(0.3);
        c.work(&snow_m, &hd, 201);
        c.wait(20.0);
        // the rise's crest caught in a lighter stroke, and the far plain
        let crest = Mask::from_fn(f, |x, y| {
            let r = rise_c(x);
            let d = (y - r).abs();
            if y > HORIZON + 2.0 { (1.0 - smoothstep(0.0, 5.0, d)) * 1.0 } else { 0.0 }
        });
        let hd = Paint::body(hex("#ebe7dc"));
        let _ = hd;
        let crest_h = paint::Handling::new(Tool::round_sable(3.0)).mixed(pal, 0.1).color(|_, _| hex("#ece8de")).angle(|_, _| 0.0).angle_jitter(0.08).length(12.0, 40.0).coverage(1.2).pressure(0.4, 0.7).clip(true).threshold(0.3).fill(false);
        c.work(&crest, &crest_h, 202);
        c.dry();
        let sp = Stipple::new(Tool::stippler(1.6)).mixed(pal, 0.3).color(|x, y| {
            let n = far.get(x * 2.0, y);
            paint::color::mix(hex("#6d7078"), hex("#8c8e92"), smoothstep(-0.3, 0.3, n), Mix::Pigment)
        }).coverage(|_, _| 1.4).pressure(0.35, 0.7).dips(14, 0.4, 0.5).clip(true);
        c.stipple(&wood_band, &sp, 203);
        // snow texture: soft touches of cooler and warmer white
        let sp = Stipple::new(Tool::stippler(3.0)).mixed(pal, 0.2).color(snow_col).coverage(|_, y| if y > HORIZON + 40.0 { 0.9 } else { 0.4 }).pressure(0.35, 0.7).dips(16, 0.4, 0.5).cluster(0.5, None).clip(true);
        c.stipple(&snow_m, &sp, 204);
        c.dry();
    }

    // ---------------------------------------------------------- tree body
    // palette of the wood (masstones to mix): an old oak's gray bark in
    // overcast light; the dead wood silver-gray
    let bark_dark = hex("#2e2722");
    let bark_mid = hex("#4a4038");
    let bark_lit = hex("#7a7266");
    let bark_cool = hex("#8a8a86");
    let dead_dark = hex("#5d5953");
    let dead_lit = hex("#b2aca0");
    if o.stage("trunk", &mut c, &mut rng) {
        // underpaint: dark umber through the whole wood, thin
        let hd = paint::Handling::new(Tool { lay: 0.7, ..Tool::filbert(8.0) })
            .mixed(pal, 0.3)
            .color(|_, _| bark_mid)
            .angle(|_, _| -FRAC_PI_2)
            .angle_jitter(0.3)
            .length(10.0, 30.0)
            .coverage(2.4)
            .clip(true)
            .threshold(0.35);
        c.work(&wood_m, &hd, 301);
        c.wait(10.0);
        // modeling each limb with strokes along it, side by side across
        // its width: shadow side (right, away from the light at the left),
        // middle, lit side; dead wood pale
        let mut r = Rng::new(o.seed + 303);
        let mut brushes: Vec<Held> = [1.5f32, 3.0, 6.0, 10.0].iter().enumerate().map(|(i, &wd)| Held::new(Tool { point: 0.6, ..Tool::round_sable(wd) }, 310 + i as u64)).collect();
        let bodies: Vec<&Br> = std::iter::once(&tree.trunk).chain(tree.limbs.iter()).chain(tree.all.iter().filter(|b| b.w[0] > 2.2)).collect();
        for b in &bodies {
            let n = b.pts.len();
            if n < 2 {
                continue;
            }
            let wmax = b.w.iter().cloned().fold(0.0, f32::max);
            // strokes across: more for wider limbs
            let lanes = ((wmax / 5.0).ceil() as usize).clamp(2, 18);
            for lane in 0..lanes {
                let u = (lane as f32 + 0.5) / lanes as f32 * 2.0 - 1.0; // -1 left .. 1 right (of the axis, facing along it)
                // stroke pieces along the limb, 30-70 units long
                let mut i0 = 0;
                while i0 < n - 1 {
                    let len_pts = (r.range(10.0, 24.0) as usize).max(3);
                    let i1 = (i0 + len_pts).min(n - 1);
                    let seg: Vec<(f32, f32)> = (i0..=i1)
                        .map(|i| {
                            let (a, e) = (b.pts[i.saturating_sub(1)], b.pts[(i + 1).min(n - 1)]);
                            let (dx, dy) = (e.0 - a.0, e.1 - a.1);
                            let l = (dx * dx + dy * dy).sqrt().max(1e-3);
                            let off = u * b.w[i] * 0.42;
                            (b.pts[i].0 - dy / l * off, b.pts[i].1 + dx / l * off)
                        })
                        .collect();
                    let wd = b.w[(i0 + i1) / 2] / lanes as f32 * 1.6;
                    // which side is lit: the normal's x pointing left
                    let mid = (i0 + i1) / 2;
                    let (a, e) = (b.pts[mid.saturating_sub(1)], b.pts[(mid + 1).min(n - 1)]);
                    let (dx, dy) = (e.0 - a.0, e.1 - a.1);
                    let l = (dx * dx + dy * dy).sqrt().max(1e-3);
                    let nx = -dy / l * u; // x-component of this lane's offset direction
                    let ny = dx / l * u;
                    // light from upper left, diffuse
                    let lit = (0.5 - 0.5 * (nx * 0.8 + ny * 0.6)).clamp(0.0, 1.0);
                    let lit = smoothstep(0.1, 0.95, lit) * (1.0 - u.abs().powi(4) * 0.5);
                    let col = if b.dead {
                        paint::color::mix(dead_dark, dead_lit, lit, Mix::Pigment)
                    } else {
                        let base = gradient(&[(0.0, bark_dark), (0.45, bark_mid), (0.85, bark_lit), (1.0, bark_cool)], lit, Mix::Pigment);
                        paint::color::mix(base, hex("#6b6a5a"), 0.25 * r.f(), Mix::Pigment)
                    };
                    let bi = if wd < 1.6 { 0 } else if wd < 3.5 { 1 } else if wd < 7.0 { 2 } else { 3 };
                    let hb = &mut brushes[bi];
                    let p = hb.tool.pressure_for(wd.min(hb.tool.width)).clamp(0.2, 1.0);
                    hb.reload(pal.paint(col, 0.2), 0.7);
                    c.drag(hb, &Gesture::new(seg).pressure(p, p * 0.9).ramps(0.1, 0.2).shake(0.4), Some(&wood_m));
                    i0 = i1.saturating_sub(1).max(i0 + 1);
                }
            }
        }
        c.wait(15.0);
    }
    o.end(&mut c, &mut rng);
    c.dry();
    c.relief(st.relief.0, st.relief.1);
    o.save(&mut c);
    let _ = (w, h, Touch::at(0.0, 0.0), dead_lit);
}

